INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quelle est la plage idéale de pH pour l''eau d''une piscine ?', '6.8 à 7.0', '7.2 à 7.4', '7.6 à 8.0', '8.2 à 8.6', 'b', '7.2-7.4 est la zone où le désinfectant est le plus efficace et l''eau la plus confortable.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Que se passe-t-il si le pH est trop haut (> 7.6) ?', 'Le chlore devient plus efficace', 'L''eau devient plus agressive pour les équipements', 'Le chlore devient moins efficace et des dépôts calcaires apparaissent', 'Rien, ce n''est jamais un problème', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quelle est la teneur idéale en chlore libre pour une piscine privée en usage courant ?', '0.2 mg/L', '2 mg/L', '5 mg/L', '10 mg/L', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Le chlore combiné (chloramines) résulte de la réaction du chlore avec :', 'Le sel', 'Les matières organiques apportées par les baigneurs', 'Le stabilisant', 'Le calcaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Une eau qui sent très fort le chlore est en réalité souvent le signe :', 'D''un excès de chlore libre', 'D''une eau parfaitement désinfectée', 'D''un taux de chlore combiné élevé (sous-chloration)', 'D''un TAC trop bas', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Au-delà de quel taux de chlore combiné faut-il faire un traitement choc ?', '0.1 mg/L', '0.4-0.6 mg/L', '2 mg/L', '5 mg/L', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Que mesure le TAC ?', 'La température de l''eau', 'Le taux de sel', 'La capacité de l''eau à résister aux variations de pH', 'La turbidité de l''eau', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quelle est la plage idéale du TAC ?', '10-30 mg/L', '80-120 mg/L', '200-300 mg/L', '500-600 mg/L', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Pourquoi faut-il toujours régler le TAC avant le pH ?', 'Ce n''est pas nécessaire, l''ordre n''a pas d''importance', 'Le TAC stabilise le pH, sinon la correction du pH est inefficace', 'Le pH influence le TAC', 'Le TAC se règle automatiquement avec le chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un TAC trop bas entraîne :', 'Un pH stable', 'Une eau entartrante', 'Un pH instable (effet yo-yo)', 'Une surconsommation de chlore uniquement', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quelle est la plage idéale de TH (dureté) recommandée ?', '10 à 20 °f (100-200 mg/L)', '50 à 60 °f', '1 à 5 °f', '80 à 100 °f', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un TH trop élevé (> 25 °f) favorise :', 'La corrosion des équipements', 'L''entartrage et une eau trouble', 'Une baisse du chlore', 'Une hausse du pH incontrôlable', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un TH trop bas expose plutôt à :', 'L''entartrage', 'La corrosion des équipements et du revêtement', 'Une odeur de chlore', 'Une eau plus claire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'À quoi sert le stabilisant (acide cyanurique) ?', 'À augmenter le pH', 'À protéger le chlore de la dégradation par les UV du soleil', 'À remplacer le TAC', 'À adoucir l''eau', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Sans stabilisant, le chlore libre en plein soleil d''été est détruit par les UV en environ :', '2 à 3 heures', '2 à 3 jours', '2 à 3 semaines', 'Il n''est jamais détruit', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quelle est la plage idéale de stabilisant selon la norme DIN EN 16713:2016 ?', '0-5 mg/L', '30 à 50 mg/L', '150-200 mg/L', '500 mg/L minimum', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quel est le maximum réglementaire français pour le stabilisant ?', '10 mg/L', '30 mg/L', '75 mg/L', '500 mg/L', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'La sur-stabilisation de l''eau provoque :', 'Un chlore de plus en plus efficace', 'Un effet de ''verrouillage'' rendant le chlore moins efficace à dose égale', 'Une baisse du TAC', 'Une hausse automatique du pH', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Comment corriger une eau sur-stabilisée ?', 'Ajouter encore plus de chlore stabilisé', 'Renouveler une partie de l''eau du bassin ou passer au chlore non stabilisé', 'Baisser le pH uniquement', 'Ajouter du sel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Que signale un indice de Langelier (LSI) proche de 0 (± 0,3) ?', 'Une eau très corrosive', 'Une eau entartrante', 'Une eau à l''équilibre calco-carbonique', 'Une eau non désinfectée', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un indice de Langelier positif signale une eau :', 'Corrosive', 'Entartrante', 'Sans chlore', 'Trop acide', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un indice de Langelier négatif signale une eau :', 'Entartrante', 'Corrosive/agressive', 'Parfaitement équilibrée', 'Trop riche en stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Dans quel ordre faut-il corriger les paramètres de l''eau ?', 'Chlore, puis pH, puis TAC', 'TAC, puis pH, puis TH, puis chlore', 'TH, puis chlore, puis TAC', 'Peu importe l''ordre', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quel réactif est utilisé pour tester le pH avec un kit à pastilles ?', 'DPD1', 'DPD3', 'Phenol Red', 'Orthotolidine', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quel réactif est utilisé pour tester le chlore libre ?', 'Phenol Red', 'DPD1', 'DPD3', 'Bleu de bromothymol', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Quel outil de mesure offre la plus grande précision, multi-paramètres ?', 'Bandelette réactive', 'Trousse à gouttes', 'Photomètre électronique', 'Le simple aspect visuel de l''eau', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Pourquoi ne faut-il jamais toucher l''embout d''un flacon réactif avec les doigts ?', 'Cela n''a aucune conséquence', 'Cela contamine le réactif et fausse les tests suivants', 'Cela accélère la réaction', 'Cela stérilise le réactif', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Combien de temps se conservent généralement les réactifs liquides (DPD, phénol red) ?', '1 semaine', '1 mois', 'Environ 1 an', '10 ans', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Où doit-on prélever l''échantillon d''eau pour un test fiable ?', 'En surface, près du bord', 'À 30-40 cm de profondeur, loin des buses et skimmers', 'Juste après avoir versé un produit', 'N''importe où, cela n''a pas d''importance', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un pH très bas (< 7,0) fausse la lecture de quel autre paramètre ?', 'Le chlore', 'Le sel', 'La température', 'Aucun', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Le chlore choc (dichlore, hypochlorite de calcium) est-il stabilisé ?', 'Oui, toujours', 'Non, il est non stabilisé', 'Cela dépend uniquement de la marque', 'Le chlore choc n''existe pas', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Les galets de chlore lent (trichlore) sont :', 'Non stabilisés', 'Stabilisés (contiennent de l''acide cyanurique)', 'Sans effet sur le pH', 'Interdits en France', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un floculant sert à :', 'Désinfecter l''eau à la place du chlore', 'Clarifier l''eau en agglomérant les particules en suspension', 'Augmenter le TAC', 'Remplacer le stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un séquestrant métaux doit être ajouté :', 'Après un traitement choc uniquement', 'Avant tout traitement choc, pour éviter que les métaux ne précipitent en taches', 'Jamais avec du chlore', 'Uniquement en hiver', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'pH+ et pH- doivent être versés :', 'Ensemble pour un effet plus rapide', 'Directement dans l''eau, jamais l''inverse, et jamais mélangés entre eux', 'Directement sur le liner', 'Dans le panier du skimmer, filtration coupée', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Quelle est la dose de référence couramment utilisée pour un chlore choc standard ?', '2 g/m³', '20 g/m³', '200 g/m³', '2 kg/m³', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Avant un traitement choc, il faut d''abord :', 'Vider la moitié du bassin', 'Ramener le pH entre 7.2 et 7.4', 'Couper la filtration', 'Ajouter du sel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Après un choc chlore, la filtration doit tourner en continu pendant au moins :', '1 heure', '24 heures', '10 minutes', '1 semaine', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Les algues vertes sont le plus souvent liées à :', 'Un excès de stabilisant uniquement', 'Un manque de désinfectant ou un pH déséquilibré', 'Un TH trop bas', 'Un excès de sel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Comment reconnaît-on les algues moutarde (jaunes) ?', 'Elles forment des taches noires dans les joints', 'Aspect poudreux jaunâtre qui se redépose vite après brossage', 'Elles ne se trouvent que sur les margelles', 'Elles rendent l''eau bleue', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Pourquoi les algues moutarde résistent-elles au chlore classique ?', 'Elles ne résistent pas, un chlore normal suffit toujours', 'Elles nécessitent un produit anti-algues moutarde spécifique en complément', 'Elles disparaissent seules en 24h', 'Elles ne sont pas de vraies algues', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Les algues noires se logent principalement :', 'En surface de l''eau', 'Dans les joints et micro-fissures, très résistantes', 'Uniquement sur les liners neufs', 'Dans le stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Pour traiter les algues noires, il faut d''abord :', 'Ajouter du sel', 'Brosser vigoureusement pour casser leur membrane protectrice avant traitement', 'Vider le bassin', 'Baisser le pH sous 6', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Les algues roses sont en réalité :', 'De vraies algues très rares', 'Des bactéries, pas de vraies algues', 'Un dépôt de calcaire coloré', 'Un signe de sur-chloration', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Les algues roses colonisent surtout :', 'Le fond du bassin uniquement', 'Les surfaces plastiques (liner, joints, paniers de skimmer)', 'Les margelles en pierre', 'L''eau en suspension uniquement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Pour rattraper une eau trouble ou laiteuse, on utilise principalement :', 'Du sel', 'Un floculant', 'Du stabilisant', 'De l''antigel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Après floculation avec un filtre à sable, il ne faut surtout pas :', 'Nettoyer le filtre après', 'Faire un backwash qui renverrait les flocons déposés au fond', 'Aspirer les dépôts', 'Attendre quelques heures', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Une eau verte translucide (sans dépôt) évoque souvent la présence de :', 'Fer', 'Cuivre (corrosion de canalisations ou électrolyseur en fin de vie)', 'Manganèse', 'Calcaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Une teinte rouille ou brune de l''eau évoque la présence de :', 'Fer', 'Cuivre', 'Chlore en excès', 'Stabilisant', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Des dépôts noirs dans l''eau évoquent la présence de :', 'Manganèse', 'Sel', 'Chlore combiné', 'TAC élevé', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Que faut-il faire avant de traiter une eau tachée par des métaux ?', 'Un choc chlore immédiat', 'Ramener le pH entre 7.0 et 7.4 puis ajouter un séquestrant, sans choc immédiat', 'Vidanger complètement le bassin', 'Augmenter le stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Le chlore stabilisé (galets) est adapté :', 'Uniquement au traitement choc ponctuel', 'À la désinfection continue d''une piscine extérieure', 'Uniquement aux spas', 'Il est interdit en France', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Le chlore non stabilisé est surtout utilisé pour :', 'L''entretien quotidien de routine', 'Le rattrapage ponctuel (eau verte) sans augmenter le stabilisant déjà présent', 'Remplacer le TAC', 'Hiverner la piscine', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Le brome, comparé au chlore, est plutôt :', 'Moins cher et identique en tout point', 'Mieux toléré par les peaux sensibles et plus stable en eau chaude', 'Interdit dans les spas', 'Impossible à doser', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'L''oxygène actif est plutôt adapté :', 'Aux grandes piscines collectives', 'Aux petits bassins/spas familiaux, sans odeur', 'Au traitement au sel uniquement', 'Aux piscines à débordement uniquement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Le taux de sel idéal pour une piscine à électrolyse est généralement de :', '0.5 à 1 g/L', '3 à 5 g/L', '20 à 30 g/L', '50 g/L', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Un électrolyseur qui ne produit pas assez de chlore doit d''abord être vérifié pour :', 'Un dépôt de tartre sur les cellules', 'Un excès de stabilisant uniquement', 'Un TAC trop bas', 'Une eau trop froide toujours', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Le PHMB (polymère) est-il compatible avec un passage direct au chlore ?', 'Oui, sans aucune précaution', 'Non, incompatible sans vidange complète préalable', 'Oui, c''est même recommandé', 'Le PHMB contient déjà du chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'UV et ozone sont des traitements :', 'Rémanents à eux seuls, remplaçant tout désinfectant', 'Complémentaires, réduisant la consommation de désinfectant chimique', 'Interdits sur les piscines privées', 'Réservés à l''eau de mer', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la finesse de filtration approximative d''un filtre à sable ?', '1-3 microns', '15-20 microns', '30-40 microns', '100 microns', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la finesse de filtration d''un filtre à cartouche ?', '1-3 microns', '15-20 microns', '30-40 microns', '200 microns', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel filtre offre l''eau la plus limpide (1-3 microns) ?', 'Filtre à sable', 'Filtre à cartouche', 'Filtre à diatomées', 'Aucun filtre n''atteint cette finesse', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Un filtre à cartouche se nettoie :', 'Par backwash comme le sable', 'Manuellement, sans backwash', 'Il ne se nettoie jamais', 'Uniquement par un professionnel agréé', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le sable d''un filtre doit être remplacé environ tous les :', '6 mois', '1 an', '5 à 7 ans', '20 ans', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Une cartouche de filtration doit être remplacée environ tous les :', '1 mois', '2 à 3 ans', '10 ans', 'Jamais', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le filtre à verre recyclé, comparé au sable, offre :', 'Une filtration plus grossière', 'Une meilleure résistance à l''entartrage et une filtration plus fine', 'Aucune différence', 'Un besoin de backwash quotidien', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Que signifie ''HMT'' pour une pompe de filtration ?', 'Hauteur Manométrique Totale', 'Haute Maintenance Technique', 'Humidité Maximale Tolérée', 'Une unité de volume', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Une pompe surdimensionnée par rapport au filtre risque de :', 'Ne rien changer', 'User prématurément le filtre', 'Réduire la consommation électrique', 'Améliorer la filtration sans inconvénient', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel est l''avantage principal d''une pompe à vitesse variable ?', 'Elle ne s''use jamais', 'Elle adapte le débit aux besoins réels, avec un gain énergétique important', 'Elle ne nécessite aucun entretien', 'Elle remplace le filtre', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Que signifie le COP d''une pompe à chaleur ?', 'Coefficient de Performance (chaleur restituée / énergie consommée)', 'Coût Officiel de Production', 'Le volume d''eau chauffé par heure', 'La durée de vie de la PAC', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le COP d''une pompe à chaleur varie en fonction :', 'De la couleur du bassin', 'De la température extérieure (il chute quand l''air se refroidit)', 'Du prix de l''électricité uniquement', 'Il est toujours constant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Dimensionnement indicatif d''une PAC : environ combien de kW pour 10 m³ d''eau ?', '0.1 kW', '1 kW', '10 kW', '100 kW', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la règle professionnelle de durée de filtration selon la température ?', 'Température × 2', 'Température ÷ 2', 'Toujours 24h/24', 'Toujours 4h/jour', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Pour une eau à 28°C, quelle filtration continue est recommandée ?', '2h/jour', '7h/jour', '14h/jour, voire continue au-delà', 'Aucune filtration nécessaire', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le robot hydraulique fonctionne grâce à :', 'Une batterie intégrée', 'Le débit d''eau généré par la pompe de filtration existante', 'L''énergie solaire', 'Un moteur diesel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le robot électrique, comparé à l''hydraulique, est :', 'Totalement autonome (aspiration et filtration embarquées)', 'Toujours moins cher', 'Incapable de nettoyer les parois', 'Interdit sur liner', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel robot sollicite le plus le préfiltre et le filtre du bassin ?', 'Le robot électrique', 'Le robot hydraulique', 'Aucun des deux', 'Les deux de manière identique', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel robot est réputé le plus fiable mécaniquement (moins de composants électroniques) ?', 'Le robot électrique', 'Le robot hydraulique', 'Ils sont identiques', 'Aucun robot n''est fiable', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Une bonde de fond doit être équipée d''un dispositif :', 'Anti-vortex / anti-entraînement', 'Anti-gel uniquement', 'Anti-calcaire', 'Il n''y a aucune obligation', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Une vanne multivoie de filtre à sable permet de sélectionner notamment :', 'Uniquement filtration ou arrêt', 'Filtration, lavage, rinçage, vidange, recirculation, hivernage', 'Uniquement le chauffage', 'Le dosage du chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'À quelle fréquence minimale faut-il vider le panier du skimmer en pleine saison ?', 'Une fois par an', 'Une fois par semaine minimum', 'Une fois toutes les deux heures', 'Jamais si le robot fonctionne', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Pour nettoyer une ligne d''eau, il faut utiliser :', 'Une brosse métallique quel que soit le revêtement', 'Un nettoyant adapté au revêtement et une éponge/pierre non abrasive', 'De l''eau de javel concentrée versée directement', 'Un nettoyeur haute pression toujours', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Pour nettoyer des margelles en pierre naturelle, il faut éviter :', 'L''eau tiède savonneuse', 'Le nettoyeur haute pression et les produits acides', 'La brosse à poils souples', 'Le bicarbonate de soude', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Sur du béton/carrelage, on peut utiliser une brosse plus agressive qu''un liner car :', 'Le carrelage est plus fragile que le liner', 'Le revêtement est plus résistant mais plus poreux (accroche des algues)', 'Le liner ne se salit jamais', 'Le béton n''accroche jamais les algues', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Après chaque cycle d''un robot électrique, il faut :', 'Le laisser dans l''eau en permanence', 'Le sortir, l''égoutter, rincer le(s) filtre(s)/panier(s)', 'Le stocker mouillé sans l''ouvrir', 'Le brancher immédiatement en charge dans l''eau', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Les brosses mousse d''un robot électrique se remplacent environ :', 'Toutes les semaines', 'Après une saison', 'Tous les 10 ans', 'Jamais', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Une piscine hors-sol/tubulaire nécessite un contrôle pH/chlore :', 'Moins fréquent qu''un bassin enterré', 'Plus fréquent (minimum 2 fois/semaine en pleine saison)', 'Une fois par an suffit', 'Ce n''est jamais nécessaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Pourquoi une piscine hors-sol se déséquilibre-t-elle plus vite qu''un bassin enterré ?', 'Elle a un plus grand volume', 'Son faible volume la rend plus sensible aux variations', 'Elle n''a jamais de traitement', 'Elle n''a pas de filtration', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Le bac tampon d''une piscine à débordement représente environ quelle part du volume du bassin ?', '1%', '10%', '50%', '100%', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Un bac tampon mal entretenu devient rapidement :', 'Un simple réservoir sans conséquence', 'Un foyer de prolifération d''algues qui contamine le bassin', 'Plus propre que le bassin lui-même', 'Inutile à vérifier', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'À quelle fréquence recommande-t-on de nettoyer un bac tampon en saison ?', 'Une fois par jour', 'Environ une fois par mois', 'Une fois tous les 5 ans', 'Jamais, il s''autonettoie', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Pour un spa/bain à remous, l''entretien du filtre doit être :', 'Moins fréquent que pour une piscine', 'Plus rapproché que pour une piscine (faible volume, forte fréquentation)', 'Inutile', 'Fait une fois par an', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Une piscine naturelle/biologique fonctionne principalement grâce :', 'À un traitement chloré renforcé', 'Au lagunage (plantes + micro-organismes filtrants)', 'À l''eau de mer', 'À l''ozone uniquement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Avant l''hivernage, il faut d''abord :', 'Vider complètement le bassin dans tous les cas', 'Nettoyer, équilibrer l''eau et faire un traitement choc', 'Couper l''électricité du local technique uniquement', 'Ajouter du sable dans le bassin', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'En hivernage passif, le niveau d''eau doit être :', 'Au maximum', 'Abaissé sous les skimmers', 'Complètement vidé', 'Inchangé', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Les gizzmos/flotteurs anti-gel se placent :', 'Dans le local technique uniquement', 'Dans les skimmers et refoulements', 'Sur les margelles', 'Dans le filtre à sable', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Au printemps, avant de relancer la filtration, il faut d''abord :', 'Faire un backwash complet du filtre', 'Ajouter directement du chlore choc sans rien vérifier', 'Couper l''eau du réseau', 'Retirer le stabilisant du bassin', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Après la remise en route, la filtration doit tourner en continu pendant environ :', '10 minutes', '24 à 48 heures', '1 mois', 'Ce n''est pas nécessaire', 'b', NULL);
