INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Que faut-il éviter avec un hors-sol vidé en plein soleil ?', 'Rien, c''est sans risque', 'Le laisser vide trop longtemps : le PVC peut se déformer', 'Le couvrir', 'Le stocker au sec', 'b', NULL);
