INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Si la fuite persiste filtration coupée, elle se situe plutôt :', 'Sur le circuit hydraulique (canalisations, pompe, filtre)', 'Sur la structure du bassin (liner, coque, pièces à sceller)', 'Elle n''existe pas', 'Dans le local technique uniquement', 'b', NULL);
