INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quelle formule permet de calculer le volume d''un bassin rectangulaire ?', 'Longueur × Largeur × Profondeur moyenne', 'Longueur + Largeur + Profondeur', 'Longueur × Largeur uniquement', 'Rayon² × π', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quelle formule permet de calculer le volume d''un bassin rond ?', 'Diamètre × Profondeur', 'Rayon² × π × Profondeur moyenne', 'Longueur × Largeur × 0.89', 'Rayon × Profondeur', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quel coefficient applique-t-on pour un bassin ovale ?', '0.5', '0.89', '1.5', '3.14', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Pour une forme libre, quelle estimation rapide utilise-t-on ?', 'Longueur max × Largeur max × Profondeur moyenne × 0.85', 'Longueur × Largeur × 2', 'Uniquement la profondeur maximale', 'Il n''existe aucune méthode d''estimation', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', '1 m³ correspond à combien de litres ?', '10 litres', '100 litres', '1 000 litres', '10 000 litres', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Pour calculer un volume, il faut privilégier :', 'La profondeur maximale', 'La profondeur moyenne', 'La profondeur minimale', 'Une profondeur fixe de 1 m toujours', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'La dose d''un produit de traitement est généralement indiquée sur l''emballage en :', 'g ou mL par m³', 'kg par piscine, sans rapport au volume', 'Litres par jour', 'Aucune indication n''est jamais donnée', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Pour un gros écart à corriger, il vaut mieux :', 'Verser toute la dose d''un coup', 'Fractionner en plusieurs apports espacés de quelques heures', 'Ne jamais dépasser une seule dose par semaine', 'Ignorer la dose indiquée', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'La formule générale de dosage du chlore choc est :', 'Dose = Volume × Concentration visée ÷ Concentration du produit', 'Dose = Volume + Concentration', 'Dose = Profondeur × pH', 'Dose = TAC × Volume', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Une eau très verte peut nécessiter de monter ponctuellement le chlore choc jusqu''à :', '1-2 g/m³', '25-30 g/m³', '500 g/m³', 'Aucune augmentation n''est jamais possible', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quelle est la règle simplifiée de durée de filtration ?', 'Température (°C) ÷ 2 = heures de filtration', 'Température × 2 = heures de filtration', 'Toujours 8h par jour, quelle que soit la température', 'Toujours 24h par jour', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'À 24°C, quelle durée de filtration la règle professionnelle recommande-t-elle ?', '6h', '12h', '20h', '24h obligatoirement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'En dessous de quelle température la filtration peut-elle être fortement réduite ?', '12°C', '20°C', '25°C', '30°C', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''est-ce qu''un skimmer ?', 'Une pompe de filtration', 'Une écumoire intégrée à la paroi qui aspire l''eau de surface', 'Un produit chimique', 'Un type de revêtement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''est-ce que le ''backwash'' ?', 'Un type d''algue', 'Le contre-lavage : inversion du sens de circulation pour nettoyer un filtre', 'Une norme de sécurité', 'Un produit anti-calcaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que désigne la ''ligne d''eau'' ?', 'Le tuyau d''aspiration principal', 'La bande à la surface où se déposent calcaire, graisses et pollens', 'Le niveau maximal légal de remplissage', 'Une norme de filtration', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''est-ce que le ''refoulement'' ?', 'La buse qui renvoie l''eau filtrée dans le bassin', 'Un défaut du filtre', 'Le rejet des eaux usées', 'Un type d''algue', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''est-ce qu''une piscine à débordement/miroir utilise pour capter l''eau de surface ?', 'Un skimmer classique uniquement', 'Des goulottes menant à un bac tampon', 'Une bonde de fond uniquement', 'Rien de spécifique', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Une piscine ''miroir'' se caractérise par :', 'Un débordement total sur tous les côtés, eau au niveau du sol', 'Une couleur miroir du liner', 'L''absence totale de filtration', 'Un traitement obligatoire au brome', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Un revêtement liner (PVC souple) est sensible à :', 'Rien, il est increvable', 'Aux perforations et à la décoloration', 'Uniquement au gel', 'Uniquement au chlore choc', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Le PVC armé, comparé au liner classique, est :', 'Moins résistant', 'Plus résistant et étanche, soudé', 'Identique en tout point', 'Interdit pour les formes complexes', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Un bassin en coque polyester est réputé pour :', 'Être très rugueux et accrocher les algues', 'Être très lisse, avec peu d''accroche pour les algues', 'Ne jamais pouvoir être réparé', 'Nécessiter un traitement spécial obligatoire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Un revêtement en béton/carrelage est plus sujet aux :', 'Algues noires dans les joints (surface poreuse)', 'Perforations comme un liner', 'Décolorations rapides', 'Aucun risque particulier', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Une piscine gonflable se caractérise par :', 'Un grand volume et une forte inertie', 'Un très faible volume, souvent renouvelé plutôt que traité en continu', 'Un équipement fixe obligatoire', 'Un traitement au sel systématique', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'La caisse à outils d''un pisciniste doit contenir en priorité :', 'Un testeur d''eau, des produits de traitement de base et des EPI', 'Uniquement un maillot de bain', 'Rien de spécifique n''est nécessaire', 'Uniquement des produits de nettoyage ménager', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Les EPI indispensables lors de la manipulation de produits concentrés sont :', 'Gants et lunettes de protection', 'Un casque de chantier uniquement', 'Aucun EPI n''est nécessaire', 'Une combinaison intégrale toujours obligatoire', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que signifie l''abréviation TAC ?', 'Titre Alcalimétrique Complet', 'Taux Automatique de Chlore', 'Test d''Analyse Chimique', 'Traitement Anti-Calcaire', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que signifie l''abréviation TH ?', 'Température Hydraulique', 'Titre Hydrotimétrique (dureté de l''eau)', 'Test Hebdomadaire', 'Traitement Hivernal', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que signifie DPD dans le contexte de l''analyse d''eau ?', 'Le nom du réactif utilisé pour mesurer le chlore', 'Un type de robot', 'Une norme de sécurité électrique', 'Un type de filtre', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que signifie ''ppm'' ?', 'Parties par million (équivalent à mg/L pour l''eau)', 'Pression Par Minute', 'Un type de pompe', 'Un produit chimique spécifique', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Dans quel ordre se déroule logiquement une tournée d''entretien type ?', 'Test pH/chlore d''abord, puis tout le reste au hasard', 'Contrôle visuel, niveau d''eau, skimmers/préfiltre, brossage, puis tests et ajustements', 'Uniquement passer le robot', 'Uniquement remplir le carnet de suivi', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Un léger trouble naissant de l''eau, même faible, doit :', 'Être ignoré jusqu''au prochain passage', 'Être corrigé avant qu''il ne s''aggrave', 'Toujours être traité par une vidange complète', 'Être signalé uniquement s''il devient vert foncé', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Une baisse de niveau d''eau plus rapide que d''habitude, sans explication, doit faire suspecter :', 'Une simple évaporation normale à ignorer', 'Une fuite potentielle', 'Un excès de chlore', 'Un TAC trop haut', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Une pompe qui se désamorce fréquemment est un signe :', 'Sans importance', 'À ne jamais laisser filer, précurseur d''une panne plus lourde', 'De TAC trop bas', 'D''un excès de stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Une odeur de chlore inhabituellement forte doit plutôt faire penser à :', 'Un manque réel de chlore libre (chlore combiné élevé)', 'Un excès de chlore actif sans aucun souci', 'Un TH trop bas', 'Rien de particulier', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Face à un doute sur un signal d''alerte pendant une visite, le bon réflexe est :', 'Attendre le prochain passage sans rien dire', 'Faire un test complémentaire ou prévenir le client tout de suite', 'Ignorer et continuer la tournée', 'Vidanger immédiatement le bassin', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'Des fissures ou décolorations sur le revêtement observées lors d''une visite doivent être :', 'Ignorées si elles ne s''aggravent pas immédiatement', 'Signalées et surveillées d''un passage à l''autre', 'Réparées immédiatement sans en avertir le client', 'Cachées pour ne pas inquiéter le client', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Analyse & routine', 'L''état des joints, vannes et raccords doit être vérifié :', 'Une seule fois à l''installation', 'Régulièrement, car ils se dégradent progressivement même avec un bon entretien', 'Jamais, ce n''est pas nécessaire', 'Uniquement en cas de fuite déjà visible', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Le chlore total correspond à :', 'Chlore libre seulement', 'Chlore libre + chlore combiné', 'Chlore combiné seulement', 'Le TAC additionné au chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Un pH trop bas rend l''eau :', 'Calcaire et douce pour la peau', 'Acide, agressive pour les équipements et la peau', 'Sans aucun effet notable', 'Automatiquement plus riche en chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Pour augmenter le pH, on utilise :', 'Du pH- (réducteur)', 'Du pH+ (rehausseur)', 'Du sel', 'Du floculant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Pour baisser le pH, on utilise :', 'Du pH+ (rehausseur)', 'Du pH- (réducteur)', 'Du stabilisant', 'Du chlore choc uniquement', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Chimie de l''eau', 'Combien de temps faut-il généralement attendre, filtration en marche, avant de recontrôler après un ajustement de pH ?', '10 secondes', '2 à 4 heures', '1 mois', 'Aucune attente n''est nécessaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Avant de traiter des algues moutarde, il faut aussi penser à laver soigneusement :', 'Uniquement les margelles', 'Le filtre, où elles se logent', 'Uniquement le robot', 'Rien d''autre que le bassin', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'Sur quel type de revêtement ne faut-il jamais utiliser de brosse inox ?', 'Le béton', 'Le carrelage', 'Le liner', 'Aucune restriction n''existe', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Traitement de l''eau', 'La cellule d''un électrolyseur doit être :', 'Jamais entretenue', 'Détartrée périodiquement en cas de dépôt blanchâtre', 'Remplacée chaque semaine', 'Nettoyée à l''eau de javel concentrée', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Un filtre à diatomées nécessite :', 'Un entretien plus technique avec rechargement périodique', 'Aucun entretien', 'Un remplacement complet chaque mois', 'Le même entretien qu''un filtre à cartouche', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Le rechargement d''un filtre à diatomées se fait généralement :', 'Par le fond du bassin', 'Par le skimmer, pompe en marche', 'Directement dans le local technique sans eau', 'Ce n''est jamais nécessaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Purger l''air d''un circuit de filtration se fait via :', 'Le purgeur d''air situé sur le dessus du filtre', 'Le skimmer uniquement', 'Le tableau électrique', 'Il n''existe pas de purgeur', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Le préfiltre de la pompe doit être nettoyé :', 'Jamais', 'Régulièrement, notamment quand il se colmate', 'Uniquement après un choc chlore', 'Uniquement en hiver', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Nettoyage', 'Un clapet anti-retour situé au fond d''un skimmer sert à :', 'Empêcher l''eau de repartir dans le mauvais sens', 'Chauffer l''eau', 'Mesurer le pH', 'Rien de particulier', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Un condensateur défectueux peut expliquer :', 'Une eau trop verte', 'Qu''un moteur monophasé peine à démarrer', 'Un excès de stabilisant', 'Une fuite sur le bassin', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Pour rechercher une fuite plus finement qu''avec le test du seau, on peut utiliser :', 'Un colorant traceur ou une électro-détection spécialisée', 'Uniquement l''odorat', 'Un test de pH', 'Aucune méthode complémentaire n''existe', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'L''hivernage actif, comparé au passif, consiste à :', 'Vider totalement le bassin', 'Laisser tourner la filtration au ralenti plutôt que de tout arrêter', 'Retirer tous les équipements', 'Ne jamais traiter l''eau', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Hivernage / Estivage', 'Pourquoi hiverner une piscine dans les régions à gel est-il important ?', 'Pour éviter l''éclatement des canalisations gelées', 'Pour économiser de l''eau uniquement', 'Pour changer la couleur du liner', 'Ce n''est utile que pour les piscines collectives', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Le port de gants et lunettes est particulièrement requis lors de :', 'La lecture du carnet sanitaire', 'La manipulation de produits chimiques concentrés', 'Le passage du robot', 'Le brossage des parois', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Un local technique doit être :', 'Fermé hermétiquement sans aucune aération', 'Aéré, à l''abri du soleil et d''une chaleur excessive', 'Toujours humide en permanence', 'Sans contrainte particulière', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Le portillon d''une barrière de piscine doit avoir :', 'Une fermeture et un verrouillage automatiques', 'Aucune fermeture nécessaire', 'Un simple loquet manuel suffit toujours', 'Une hauteur inférieure à la barrière', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Le volume d''un bassin ovale de 8m × 4m × 1.5m de profondeur moyenne est environ :', '16 m³', '42.7 m³', '48 m³', '96 m³', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Pourquoi utilise-t-on un coefficient réducteur (0.85, 0.89) pour les formes ovales/libres ?', 'Pour majorer le volume par sécurité', 'Car ces formes contiennent moins d''eau qu''un simple rectangle de mêmes dimensions', 'Ce coefficient n''a aucune justification', 'Pour compenser le stabilisant', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''appelle-t-on communément le ''local technique'' ?', 'L''endroit où se trouvent pompe, filtre et éventuellement PAC/électrolyseur', 'Le vestiaire du client', 'Le skimmer principal', 'La zone de baignade peu profonde', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Que désigne une ''plage'' de piscine ?', 'Le pourtour aménagé autour du bassin', 'Une zone de baignade peu profonde', 'Un type de filtre', 'Un produit de traitement', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Qu''est-ce qu''un ''diffuseur flottant'' ?', 'Un accessoire flottant contenant des galets de chlore lent', 'Un type de robot', 'Un instrument de mesure du pH', 'Une pièce du filtre à sable', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Glossaire', 'Une ''pièce à sceller'' désigne :', 'Un élément fixé dans la structure du bassin (skimmer, buse, projecteur...)', 'Un outil de mesure', 'Un produit chimique', 'Un type de couverture de sécurité', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Pourquoi une pompe de filtration piscine est-elle dite « auto-amorçante » ?', 'Elle démarre toute seule à heure fixe', 'Son préfiltre garde une réserve d''eau qui lui permet de se réamorcer', 'Elle n''a pas besoin d''électricité', 'Elle aspire l''air aussi bien que l''eau', 'b', 'Le préfiltre rempli d''eau sert de réserve d''amorçage : c''est aussi pour ça qu''on le remplit manuellement après une intervention.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quel est le rôle du diffuseur dans une pompe centrifuge ?', 'Filtrer les débris', 'Refroidir le moteur', 'Convertir la vitesse de l''eau en pression et empêcher le retour du flux', 'Doser le chlore', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Que se passe-t-il si une pompe tourne à sec quelques minutes ?', 'Rien, elle est prévue pour', 'La garniture mécanique, lubrifiée par l''eau, est détruite', 'Le condensateur explose', 'Le débit augmente', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Où le surpresseur d''un robot à pression prélève-t-il l''eau ?', 'Directement dans le bassin', 'Avant la pompe de filtration', 'Après le filtre, pour la renvoyer sous pression vers la prise balai', 'Dans le skimmer', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Un surpresseur doit être asservi électriquement pour ne fonctionner que si :', 'La pompe à chaleur est allumée', 'La pompe de filtration tourne', 'Le robot est sorti de l''eau', 'Il fait jour', 'b', 'Il aspire l''eau du circuit : sans filtration en marche, il tourne à sec et se détruit.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quel débit vise-t-on pour une nage à contre-courant permettant de nager réellement ?', '5-10 m³/h', '15-20 m³/h', '50-60 m³/h', '200 m³/h', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Sur une vanne 6 voies, la position « Circulation » fait passer l''eau :', 'À travers le filtre puis à l''égout', 'De la pompe directement aux refoulements, sans passer par le filtre', 'À contre-courant dans le filtre', 'Nulle part, tout est fermé', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quand utilise-t-on la position « Égout » (Waste) de la vanne 6 voies ?', 'Pour la filtration quotidienne', 'Pour aspirer une eau très chargée (algues, floculant) sans encrasser le filtre, ou baisser le niveau', 'Uniquement en hiver', 'Pour nettoyer les skimmers', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'À quoi sert la position « Rinçage » juste après un contre-lavage ?', 'À rincer les canalisations du bassin', 'À retasser le média filtrant et envoyer les résidus à l''égout au lieu du bassin', 'À vider complètement le filtre', 'Elle ne sert à rien', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quelle est la règle d''or absolue avant de manœuvrer une vanne multivoies ?', 'Ouvrir le couvercle du préfiltre', 'Mettre des gants', 'Arrêter la pompe', 'Fermer les skimmers', 'c', 'Sous pression, le boisseau cisaille le joint étoile et le coup de bélier peut fissurer la vanne.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Pourquoi laisse-t-on la poignée de la vanne 6 voies entre deux crans (ou sur un cran « hivernage ») pendant l''hiver ?', 'Pour laisser l''eau circuler', 'Pour décoller le boisseau du joint étoile et éviter qu''il reste comprimé tout l''hiver', 'Pour vidanger le bassin', 'C''est une erreur, il ne faut jamais le faire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'En position « Filtration », de l''eau s''écoule en continu vers l''égout. Quelle est la cause la plus probable ?', 'Le niveau du bassin est trop haut', 'Le joint étoile de la vanne multivoies est usé', 'Le sable est trop vieux', 'La pompe est trop puissante', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Un by-pass complet (pour PAC, réchauffeur...) est constitué de :', '1 vanne', '2 vannes', '3 vannes (centrale + entrée + sortie)', '6 vannes', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Sur un by-pass de PAC, fermer progressivement la vanne centrale a pour effet :', 'De diminuer le débit dans la PAC', 'D''augmenter le débit qui traverse la PAC', 'D''arrêter la filtration', 'De vider l''échangeur', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Pourquoi faut-il vidanger l''échangeur de la PAC avant l''hiver ?', 'Pour économiser l''eau', 'Parce qu''un échangeur titane qui gèle est détruit', 'Pour éviter les algues', 'Ce n''est pas nécessaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quel est l''ordre correct des équipements dans le circuit hydraulique ?', 'Pompe → traitement → filtre → chauffage', 'Pompe → filtre → chauffage → traitement → refoulements', 'Filtre → pompe → chauffage', 'Traitement → filtre → pompe', 'b', 'L''injection de traitement se fait toujours le plus en aval possible pour protéger les équipements de l''eau concentrée en produit.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Quelle répartition d''aspiration applique-t-on classiquement en saison ?', '100% bonde de fond', 'Environ 2/3 skimmers et 1/3 bonde de fond', '100% skimmers', '50% prise balai', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Parmi les rôles de la bonde de fond, on trouve :', 'Chauffer l''eau du fond', 'Aspirer l''eau la plus froide/chargée et sécuriser l''alimentation de la pompe si le niveau baisse', 'Injecter le chlore', 'Mesurer le pH', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Un clapet anti-retour à l''aspiration sert notamment à :', 'Augmenter le débit', 'Maintenir l''amorçage quand la pompe est au-dessus du plan d''eau', 'Filtrer les feuilles', 'Réduire le bruit', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Une vanne 3 voies type Jandy permet :', 'De filtrer plus fin', 'De répartir un flux entre deux directions (tout A, tout B ou mélange)', 'De remplacer le filtre', 'De chauffer l''eau', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Équipements & hydraulique', 'Pour limiter les pertes de charge, on préfère remplacer un coude 90° par :', 'Deux coudes 45°', 'Un bouchon', 'Un coude 90° plus petit', 'Un té', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la finesse de filtration d''un filtre à sable classique (sans floculant) ?', '2-5 microns', '30-40 microns', '100-200 microns', '1 mm', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel système de filtration offre la meilleure finesse du marché (2-5 microns) ?', 'Le filtre à sable', 'Le filtre à cartouche', 'Le filtre à diatomées', 'Le filtre à poche 30 microns', 'c', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quel média filtrant adsorbe aussi l''ammonium, réduisant chloramines et odeur de chlore ?', 'Le sable de silice', 'La zéolite', 'Le gravier', 'Les balles filtrantes', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la finesse réelle d''un verre filtrant standard (hors verre activé haut de gamme) ?', '1-5 microns', '15-20 microns', '50-60 microns', '100 microns', 'b', 'Les « 1-5 microns » des publicités correspondent au verre activé type AFM utilisé AVEC floculation.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Les poches filtrantes type Desjoyaux existent en finesses :', '6, 15 et 30 microns', '1, 2 et 3 microns', '50, 100 et 200 microns', 'Une seule finesse universelle', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'À partir de quelle hausse de pression au manomètre déclenche-t-on un contre-lavage ?', '+0,05 bar', '+0,3 à +0,5 bar au-dessus de la pression de référence', '+2 bars', 'On ne se fie jamais au manomètre', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Combien de temps dure un contre-lavage correctement mené ?', '10 secondes', '2 à 3 minutes, jusqu''à ce que l''eau soit claire dans le voyant', '30 minutes minimum', '2 heures', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Avec quel type de filtre le floculant est-il compatible ?', 'Tous les filtres', 'Uniquement le filtre à sable (ou verre)', 'Uniquement la cartouche', 'Uniquement les diatomées', 'b', 'Le floculant colmate irrémédiablement cartouches, poches et diatomées.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Quelle est la vitesse de filtration maximale admise pour un filtre piscine ?', '5 m³/h/m²', '50 m³/h/m²', '500 m³/h/m²', 'Aucune limite', 'b', 'Filtrer plus vite = filtrer moins bien : les impuretés traversent le média et les crépines peuvent casser.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Filtration', 'Charge type d''un filtre à sable :', '100% gravier', 'Sable 0,4-0,8 mm sur un lit de gravier 2-4 mm qui protège les crépines', 'Sable fin de plage', 'Terre de diatomées pure', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Une pompe monophasée bourdonne à la mise sous tension mais ne démarre pas. Cause n°1 ?', 'Le filtre est sale', 'Le condensateur est mort', 'Le pH est trop haut', 'Le skimmer est bouché', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Par quoi remplace-t-on un condensateur défectueux ?', 'Un condensateur de capacité double', 'Un condensateur de même capacité (tolérance ±5%)', 'N''importe quel condensateur', 'Un fusible', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Avant de manipuler un condensateur, il faut :', 'Le chauffer', 'Le décharger en court-circuitant ses bornes avec un tournevis isolé', 'Le plonger dans l''eau', 'Rien de particulier', 'b', 'Il peut conserver une charge dangereuse même hors tension.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Une fuite goutte à goutte entre le corps de pompe et le moteur signale :', 'Un joint de couvercle sec', 'Une garniture mécanique usée', 'Un préfiltre plein', 'Un excès de chlore', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Dans le cas standard, une turbine de pompe se dévisse :', 'Dans le sens horaire', 'Dans le sens anti-horaire (le filetage est serré par la rotation du moteur)', 'Elle ne se dévisse jamais', 'Avec un marteau', 'b', 'Le filetage inversé existe sur certains modèles : toujours vérifier la notice avant de forcer.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Un bruit de « cailloux » ou de graviers dans la pompe, préfiltre pourtant plein, signale :', 'Une prise d''air', 'De la cavitation', 'Un roulement neuf', 'Un excès de sel', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Des bulles aux refoulements et un couvercle de préfiltre jamais complètement plein signalent :', 'Une cavitation', 'Une prise d''air à l''aspiration', 'Un filtre trop propre', 'Un TAC trop haut', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Dépannage matériel', 'Un moteur triphasé branché dans le mauvais sens de rotation :', 'Ne démarre pas du tout', 'Débite mal, souvent sans bruit anormal', 'Disjoncte immédiatement', 'Tourne normalement', 'b', 'À vérifier systématiquement au branchement d''une pompe tri.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Loi d''affinité des pompes : si on divise la vitesse de rotation par 2, la puissance absorbée est divisée par :', '2', '4', '8', '16', 'c', 'P ∝ N³ : c''est tout l''intérêt des pompes à vitesse variable (65-85% d''économies).');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Comment calcule-t-on le débit de pompe requis pour une piscine ?', 'Volume ÷ 2', 'Volume ÷ 4 (recyclage en 4h), majoré d''environ 20% pour les pertes de charge', 'Volume × 4', 'Toujours 10 m³/h', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quel débit maximal peut accepter un filtre Ø600 (0,28 m² de surface filtrante) ?', '~5 m³/h', '~14 m³/h', '~50 m³/h', '~100 m³/h', 'b', 'Surface × 50 m³/h/m² : Ø500 → ~9,8 ; Ø600 → ~14 ; Ø750 → ~22 m³/h.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Quelle vitesse d''eau maximale vise-t-on dans une canalisation d''aspiration ?', '0,1 m/s', '1,5 m/s', '5 m/s', '15 m/s', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Calculs & formules', 'Les pertes de charge d''une canalisation varient environ en :', '1/D (inverse du diamètre)', '1/D⁵ (inverse du diamètre à la puissance 5)', 'D² (carré du diamètre)', 'Elles ne dépendent pas du diamètre', 'b', 'D''où la règle : mieux vaut un tuyau trop gros que trop petit.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Quel équipement est obligatoire sur une bonde de fond pour prévenir le risque d''emprisonnement ?', 'Un éclairage LED', 'Une grille anti-vortex conforme (type XP P90-314)', 'Un thermomètre', 'Un skimmer supplémentaire', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Quelle vitesse maximale de passage de l''eau vise-t-on à travers une grille d''aspiration ?', '0,5 m/s', '2 m/s', '5 m/s', '10 m/s', 'a', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Pour les fortes aspirations, deux bondes de fond sur la même ligne doivent être espacées d''au moins :', '10 cm', '50 cm', '2 m (référentiel européen EN 16713-2)', '10 m', 'c', 'Si l''une est obstruée par un corps, l''autre casse la dépression.');
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Le rejet sauvage des eaux de vidange dans la nature est sanctionné par :', 'Aucun texte', 'L''article L216-6 du Code de l''environnement (jusqu''à 2 ans et 75 000 € en cas de pollution)', 'Une simple contravention de stationnement', 'La norme NF P90-308', 'b', NULL);
INSERT INTO quiz_questions (category, question, option_a, option_b, option_c, option_d, correct, explanation) VALUES ('Réglementation & sécurité', 'Après un collage de PVC pression, combien de temps attendre avant la mise en pression complète ?', '5 minutes', '1 heure', '24h minimum (48h par temps froid)', '1 semaine', 'c', NULL);
